def semver_sort(versions):
    def parse_version(version_str):
        # Split version into core and build metadata
        if '+' in version_str:
            core, build = version_str.split('+', 1)
        else:
            core = version_str
            build = ''

        # Split core into version number and pre-release
        if '-' in core:
            version_part, prerelease = core.split('-', 1)
        else:
            version_part = core
            prerelease = ''

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(version_str):
        major, minor, patch, prerelease_identifiers = parse_version(version_str)

        # Versions with pre-release come before versions without
        # If prerelease_identifiers is empty, it should sort after non-empty
        # So we use (False, ...) for versions with pre-release
        # and (True, ...) for versions without
        has_no_prerelease = not prerelease_identifiers

        return (major, minor, patch, has_no_prerelease, prerelease_identifiers)

    return sorted(versions, key=sort_key)

